style.css:
/* Matcha-Themed YouTube Dark UI */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("youtube.com") {
body {
        background: radial-gradient(circle, #2a002a, #1a1a1a) !important;
        color: #fff !important;
        font-weight: 400 !important;
    }

    /* Full-page Gradient Background */
    ytd-app {
        background: radial-gradient(circle, #2a002a, #1a1a1a) !important;
    }

    /* Sidebar and Headers */
    #guide-content, ytd-mini-guide-renderer, ytd-guide-section-renderer {
        background: radial-gradient(circle, #330033, #111) !important;
    }

    /* Video Titles and Links */
    a, h1, h2, h3, h4, h5, h6 {
        color: #ff66cc !important;
        font-weight: 500 !important;
    }

    /* Buttons */
    button, ytd-button-renderer, ytd-toggle-button-renderer {
        background: rgba(255, 102, 204, 0.2) !important; /* Lower opacity */
        border: none !important;
        color: #fff !important;
        font-weight: 400 !important; /* Make text less bold */
        transition: 0.3s ease-in-out;
        text-shadow: none !important; /* Remove glow effect */
    }

    button:hover, ytd-button-renderer:hover, ytd-toggle-button-renderer:hover {
        background: rgba(255, 51, 153, 0.2) !important; /* Lower hover opacity */
        color: #ddd !important; /* Softer hover text */
    }

    /* Notification and Create Button Fix */
    ytd-topbar-menu-button-renderer, ytd-create-button-renderer {
        background: rgba(255, 102, 204, 0.2) !important;
        border: none !important;
        box-shadow: none !important;
    }

    ytd-topbar-menu-button-renderer:hover, ytd-create-button-renderer:hover {
        background: rgba(255, 51, 153, 0.2) !important;
    }

    /* Remove Borders and Extra Highlights */
    ytd-topbar-menu-button-renderer, ytd-create-button-renderer, ytd-masthead button, 
    .ytd-rich-grid-media, .ytd-video-renderer, .ytd-compact-video-renderer, 
    .ytd-rich-item-renderer, .ytd-playlist-renderer, .ytd-grid-video-renderer {
        border: none !important;
        outline: none !important;
        box-shadow: none !important;
        background: transparent !important;
    }

    /* Progress Bar */
    .ytp-progress-bar {
        background: #ff66cc !important;
    }

    /* Video Player */
    .html5-video-player {
        background: #000 !important;
    }

    /* Comments Section */
    #comments {
        background: radial-gradient(circle, #330033, #222) !important;
        border-radius: 8px !important;
    }

    /* Search Bar */
    #search-form {
        border: 1px solid rgba(255, 102, 204, 0.2) !important;
        background: radial-gradient(circle, #222, #ff66cc) !important;
    }

    /* Glow Effect */
    * {
        text-shadow: none !important; /* Remove glow */
    }

    /* Change YouTube Logo to Custom Image */
    #logo img, .ytd-topbar-logo-renderer img {
        content: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR0YyevXtkvXTQI59R7tzY14FkaukPiPkSAlA&s") !important;
        width: 120px !important;
        height: auto !important;
    }
}
